// ===== eingebettet aus src/fehlerklassen.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const fehlerklassen = (() => {
const module = { exports: {} };
// Fehlerklassen und Statuscode-Mapping (Masterprompt 3, Bauplan 3).
// EPA-Fehler werden als Text "[EPA:<status>:<CODE>:<Vorgangs-ID|->] <Meldung>" geworfen,
// damit der Error-Handler (EPA-05) sie aus execution.error.message zurücklesen kann.

const FEHLERCODES = Object.freeze({
	UNGUELTIGES_FORMAT: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNGUELTIGER_AUSLOESER: { status: 400, klasse: 'Eingabe', retrybar: false },
	UNBEKANNTER_STATUS: { status: 400, klasse: 'Eingabe', retrybar: false },
	AUTH_FEHLER: { status: 401, klasse: 'Authentifizierung', retrybar: false },
	KEINE_BERECHTIGUNG: { status: 403, klasse: 'Authentifizierung', retrybar: false },
	VORGANG_NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	KONFIG_NICHT_GEFUNDEN: { status: 404, klasse: 'Konfiguration', retrybar: false },
	NICHT_GEFUNDEN: { status: 404, klasse: 'Nicht gefunden', retrybar: false },
	DUPLIKAT: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_STATUSWECHSEL: { status: 409, klasse: 'Konflikt', retrybar: false },
	UNZULAESSIGER_AUSLOESER: { status: 409, klasse: 'Konflikt', retrybar: false },
	VERSIONSKONFLIKT: { status: 409, klasse: 'Konflikt', retrybar: true },
	GESPERRT: { status: 409, klasse: 'Konflikt', retrybar: true },
	KONFIG_MEHRDEUTIG: { status: 409, klasse: 'Konfiguration', retrybar: false },
	FREIGABE_ABGELAUFEN: { status: 410, klasse: 'Freigabe', retrybar: false },
	EXTRAKTION_UNGUELTIG: { status: 422, klasse: 'LLM', retrybar: false },
	KONFIGURATIONSFEHLER: { status: 424, klasse: 'Konfiguration', retrybar: false },
	RATE_LIMIT: { status: 429, klasse: 'Upstream', retrybar: true },
	UPSTREAM_FEHLER: { status: 502, klasse: 'Upstream', retrybar: true },
	NICHT_ERREICHBAR: { status: 503, klasse: 'Upstream', retrybar: true },
	ZEITUEBERSCHREITUNG: { status: 504, klasse: 'Upstream', retrybar: true },
	UNBEKANNT: { status: 500, klasse: 'Unbekannt', retrybar: false },
});

const EPA_MUSTER = /^\[EPA:(\d{3}):([A-Z_]+):([^\]]*)\]\s*([\s\S]*)$/;

function formatEpaFehler(code, vorgangsId, meldung) {
	const def = FEHLERCODES[code] || FEHLERCODES.UNBEKANNT;
	return `[EPA:${def.status}:${FEHLERCODES[code] ? code : 'UNBEKANNT'}:${vorgangsId || '-'}] ${meldung || ''}`.trim();
}

/** Wirft einen EPA-Fehler (für Code-Nodes). */
function epaFehler(code, vorgangsId, meldung) {
	const err = new Error(formatEpaFehler(code, vorgangsId, meldung));
	err.epaCode = code;
	return err;
}

function parseEpaFehler(text) {
	if (typeof text !== 'string') return null;
	// n8n stellt der Meldung manchmal Präfixe voran; das Muster darf irgendwo in der ersten Zeile beginnen.
	const start = text.indexOf('[EPA:');
	if (start < 0) return null;
	const m = text.slice(start).match(EPA_MUSTER);
	if (!m) return null;
	return {
		status: Number(m[1]),
		code: m[2],
		vorgangsId: m[3] === '-' ? null : m[3],
		meldung: m[4].trim(),
	};
}

/** Entfernt personenbezogene Daten und kürzt (keine Mail-Inhalte im Fehlerlog). */
function bereinigeMeldung(text, maxLaenge = 300) {
	if (text === undefined || text === null) return '';
	let s = String(text)
		.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '<email>')
		.replace(/\+?\d[\d\s/().-]{7,}\d/g, '<nummer>')
		.replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/g, 'Bearer <token>')
		.replace(/\s+/g, ' ')
		.trim();
	if (s.length > maxLaenge) s = s.slice(0, maxLaenge - 1) + '…';
	return s;
}

function codeAusHttpStatus(status) {
	const n = Number(status);
	if (!Number.isFinite(n)) return null;
	if (n === 400 || n === 422) return 'UNGUELTIGES_FORMAT';
	if (n === 401) return 'AUTH_FEHLER';
	if (n === 403) return 'KEINE_BERECHTIGUNG';
	if (n === 404) return 'NICHT_GEFUNDEN';
	if (n === 408 || n === 504) return 'ZEITUEBERSCHREITUNG';
	if (n === 409) return 'DUPLIKAT';
	if (n === 429) return 'RATE_LIMIT';
	if (n === 503) return 'NICHT_ERREICHBAR';
	if (n >= 500 && n < 600) return 'UPSTREAM_FEHLER';
	return null;
}

function codeAusText(text) {
	const t = String(text || '');
	if (/timed? ?out|ETIMEDOUT|ESOCKETTIMEDOUT|timeout of \d+ms/i.test(t)) return 'ZEITUEBERSCHREITUNG';
	if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|socket hang up|service unavailable/i.test(t)) return 'NICHT_ERREICHBAR';
	if (/rate.?limit|too many requests/i.test(t)) return 'RATE_LIMIT';
	if (/invalid_grant|unauthori[sz]ed|token (has )?expired|invalid.?token|authentication failed|password authentication/i.test(t)) return 'AUTH_FEHLER';
	if (/forbidden|insufficient privileges|access denied|permission denied/i.test(t)) return 'KEINE_BERECHTIGUNG';
	if (/duplicate key|unique constraint/i.test(t)) return 'DUPLIKAT';
	return null;
}

/**
 * Klassifiziert einen Fehler.
 * @param {{message?: string, description?: string, httpCode?: string|number}} fehler
 */
function klassifiziereFehler(fehler) {
	const f = fehler || {};
	const epa = parseEpaFehler(f.message) || parseEpaFehler(f.description);
	let code;
	let vorgangsId = null;
	let meldung;
	if (epa) {
		code = FEHLERCODES[epa.code] ? epa.code : 'UNBEKANNT';
		vorgangsId = epa.vorgangsId;
		meldung = epa.meldung;
	} else {
		code = codeAusHttpStatus(f.httpCode) || codeAusText(`${f.message || ''} ${f.description || ''}`) || 'UNBEKANNT';
		meldung = f.message || f.description || '';
	}
	const def = FEHLERCODES[code];
	return {
		statuscode: def.status,
		fehlercode: code,
		klasse: def.klasse,
		retrybar: def.retrybar,
		vorgangsId,
		meldung: bereinigeMeldung(meldung),
	};
}

/**
 * Baut aus der Ausgabe des Error Trigger einen Fehlerlog-Eintrag (ohne Mail-Inhalte).
 * Error Trigger liefert entweder {execution, workflow} oder bei Trigger-Fehlern {trigger, workflow}.
 */
function ausErrorTrigger(json) {
	const j = json || {};
	const exec = j.execution || {};
	const err = exec.error || (j.trigger && j.trigger.error) || {};
	const k = klassifiziereFehler({
		message: err.message,
		description: err.description,
		httpCode: err.httpCode,
	});
	const node = (err.node && err.node.name) || exec.lastNodeExecuted || null;
	const workflow = j.workflow || {};
	return {
		statuscode: k.statuscode,
		fehlercode: k.fehlercode,
		klasse: k.klasse,
		retrybar: k.retrybar,
		workflow_id: workflow.id || null,
		workflow_name: workflow.name || null,
		node,
		execution_id: exec.id !== undefined && exec.id !== null ? String(exec.id) : null,
		execution_url: exec.url || null,
		modus: exec.mode || (j.trigger && j.trigger.mode) || null,
		vorgangs_id: k.vorgangsId,
		meldung: k.meldung,
	};
}

function escapeHtml(s) {
	return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function alarmHtml(eintrag) {
	const e = eintrag;
	const zeilen = [
		`<b>EPA-Fehler ${e.statuscode} ${escapeHtml(e.fehlercode)}</b> (${escapeHtml(e.klasse)})`,
		`Workflow: ${escapeHtml(e.workflow_name || e.workflow_id || '?')}`,
		`Node: ${escapeHtml(e.node || '?')}`,
		`Vorgang: ${escapeHtml(e.vorgangs_id || '–')}`,
		`Meldung: ${escapeHtml(e.meldung || '–')}`,
		e.retrybar ? 'Hinweis: vorübergehender Fehler, erneuter Versuch kann helfen.' : 'Hinweis: dauerhafter Fehler, bitte prüfen.',
	];
	if (e.execution_url) zeilen.push(`<a href="${escapeHtml(e.execution_url)}">Ausführung ${escapeHtml(e.execution_id)} öffnen</a>`);
	return zeilen.join('<br>');
}

module.exports = {
	FEHLERCODES,
	formatEpaFehler,
	epaFehler,
	parseEpaFehler,
	bereinigeMeldung,
	klassifiziereFehler,
	ausErrorTrigger,
	alarmHtml,
	escapeHtml,
};
return module.exports;
})();
// ===== Ende src/fehlerklassen.js =====
// ===== eingebettet aus src/statusMatrix.js – nicht hier bearbeiten, sondern im Repo (npm run build) =====
const statusMatrix = (() => {
const module = { exports: {} };
// Statusmodell und erlaubte Übergänge (Masterprompt 4.4, Bauplan 2.2).
// Einzige Quelle der Wahrheit: wird in den Code-Node von "EPA SW Status setzen" eingebettet.

const STATUS = Object.freeze({
	NEU: 'Neu',
	ZUORDNUNG_UNKLAR: 'Zuordnung unklar',
	IGNORIERT: 'Ignoriert',
	KLASSIFIZIERUNG_UNKLAR: 'Klassifizierung unklar',
	IN_PRUEFUNG: 'In Prüfung',
	BEREIT: 'Bereit zur Bearbeitung',
	LUECKEN: 'Lücken erkannt',
	FREIGABE: 'Freigabe ausstehend',
	WARTEN: 'Warten auf Kunde',
	ESKALIERT: 'Eskaliert / Manuell',
	ABGESCHLOSSEN: 'Abgeschlossen',
});

const ALLE_STATUS = Object.freeze(Object.values(STATUS));
const ENDSTATUS = Object.freeze([STATUS.ABGESCHLOSSEN, STATUS.IGNORIERT]);

// Auslöser-Typen. Mitarbeiter werden als "Mitarbeiter:<Name oder UPN>" übergeben.
const AUSLOESER = Object.freeze(['KI', 'System', 'Cronjob', 'Mitarbeiter']);

const S = STATUS;
const MA = ['Mitarbeiter'];

// [von, nach, erlaubte Auslöser]
const UEBERGAENGE = [
	[null, S.NEU, ['System']],

	[S.NEU, S.IGNORIERT, ['KI', 'System']],
	[S.NEU, S.ZUORDNUNG_UNKLAR, ['System']],
	[S.NEU, S.KLASSIFIZIERUNG_UNKLAR, ['KI', 'System']],
	[S.NEU, S.IN_PRUEFUNG, ['KI', 'System']],

	[S.ZUORDNUNG_UNKLAR, S.IN_PRUEFUNG, MA],
	[S.ZUORDNUNG_UNKLAR, S.KLASSIFIZIERUNG_UNKLAR, ['KI', 'System']],
	[S.ZUORDNUNG_UNKLAR, S.IGNORIERT, MA],
	// Mitarbeiter ordnet die Mail einem bestehenden Vorgang zu: der temporäre Vorgang wird geschlossen.
	[S.ZUORDNUNG_UNKLAR, S.ABGESCHLOSSEN, MA],

	[S.KLASSIFIZIERUNG_UNKLAR, S.IN_PRUEFUNG, MA],
	[S.KLASSIFIZIERUNG_UNKLAR, S.IGNORIERT, MA],

	// Fehlklassifizierung korrigieren: nie löschen, Mitarbeiter kann zurückholen.
	[S.IGNORIERT, S.IN_PRUEFUNG, MA],

	[S.IN_PRUEFUNG, S.BEREIT, ['System']],
	[S.IN_PRUEFUNG, S.LUECKEN, ['System']],

	[S.LUECKEN, S.FREIGABE, ['System']],
	[S.LUECKEN, S.ESKALIERT, ['System']],

	[S.FREIGABE, S.WARTEN, MA],
	[S.FREIGABE, S.ESKALIERT, MA],
	// Neuer Kundeneingang, während noch eine Freigabe offen ist: Entwurf ist veraltet.
	[S.FREIGABE, S.IN_PRUEFUNG, ['System']],

	[S.WARTEN, S.IN_PRUEFUNG, ['System']],
	[S.WARTEN, S.FREIGABE, ['Cronjob']],
	[S.WARTEN, S.ESKALIERT, ['Cronjob', 'System']],

	[S.BEREIT, S.ABGESCHLOSSEN, MA],
	[S.BEREIT, S.IN_PRUEFUNG, ['System']],

	[S.ESKALIERT, S.IN_PRUEFUNG, MA],
	[S.ESKALIERT, S.ABGESCHLOSSEN, MA],
];

// Error-Handler darf jeden laufenden Vorgang sichern (Masterprompt Phase F).
const SYSTEM_ESKALATION_VON = ALLE_STATUS.filter(
	(s) => !ENDSTATUS.includes(s) && s !== S.ESKALIERT,
);

function ausloeserTyp(ausloeser) {
	if (typeof ausloeser !== 'string' || ausloeser.trim() === '') return null;
	const typ = ausloeser.split(':')[0].trim();
	if (typ === 'Mitarbeiter') {
		const name = ausloeser.slice(ausloeser.indexOf(':') + 1).trim();
		return ausloeser.includes(':') && name ? 'Mitarbeiter' : null;
	}
	return AUSLOESER.includes(typ) && !ausloeser.includes(':') ? typ : null;
}

/**
 * Prüft einen Statusübergang.
 * @returns {{erlaubt: boolean, statuscode: number, code: string, grund: string}}
 */
function pruefeUebergang(alt, neu, ausloeser) {
	const ablehnen = (code, grund) => ({ erlaubt: false, statuscode: 409, code, grund });
	const typ = ausloeserTyp(ausloeser);
	if (!typ) {
		return { erlaubt: false, statuscode: 400, code: 'UNGUELTIGER_AUSLOESER', grund: `Auslöser "${ausloeser}" ist ungültig` };
	}
	if (!ALLE_STATUS.includes(neu)) {
		return { erlaubt: false, statuscode: 400, code: 'UNBEKANNTER_STATUS', grund: `Status "${neu}" ist unbekannt` };
	}
	if (alt !== null && !ALLE_STATUS.includes(alt)) {
		return { erlaubt: false, statuscode: 400, code: 'UNBEKANNTER_STATUS', grund: `Status "${alt}" ist unbekannt` };
	}
	if (alt === neu) return ablehnen('UNZULAESSIGER_STATUSWECHSEL', `Status ist bereits "${neu}"`);

	if (neu === S.ESKALIERT && typ === 'System' && SYSTEM_ESKALATION_VON.includes(alt)) {
		return { erlaubt: true, statuscode: 200, code: 'OK', grund: 'Systemeskalation' };
	}
	const regel = UEBERGAENGE.find(([v, n]) => v === alt && n === neu);
	if (!regel) return ablehnen('UNZULAESSIGER_STATUSWECHSEL', `"${alt}" -> "${neu}" ist nicht erlaubt`);
	if (!regel[2].includes(typ)) {
		return ablehnen('UNZULAESSIGER_AUSLOESER', `"${alt}" -> "${neu}" ist für Auslöser "${typ}" nicht erlaubt`);
	}
	return { erlaubt: true, statuscode: 200, code: 'OK', grund: '' };
}

function erlaubteFolgestatus(alt, ausloeser) {
	return ALLE_STATUS.filter((neu) => pruefeUebergang(alt, neu, ausloeser).erlaubt);
}

module.exports = {
	STATUS,
	ALLE_STATUS,
	ENDSTATUS,
	AUSLOESER,
	UEBERGAENGE,
	pruefeUebergang,
	erlaubteFolgestatus,
	ausloeserTyp,
};
return module.exports;
})();
// ===== Ende src/statusMatrix.js =====

// ----- Node-Logik -----
const TYPEN = ['STATUS', 'MERGE', 'FREIGABE', 'ZUORDNUNG', 'DEDUPE', 'SYSTEM'];
const e = $input.first().json;
const vorgangsId = typeof e.vorgangs_id === 'string' && e.vorgangs_id.trim() ? e.vorgangs_id.trim() : null;
if (typeof e.kunde_id !== 'string' || !e.kunde_id.trim()) throw fehlerklassen.epaFehler('UNGUELTIGES_FORMAT', vorgangsId, 'kunde_id fehlt');
if (!TYPEN.includes(e.typ)) throw fehlerklassen.epaFehler('UNGUELTIGES_FORMAT', vorgangsId, `Audit-Typ "${e.typ}" ist unbekannt`);
if (!statusMatrix.ausloeserTyp(e.ausloeser)) throw fehlerklassen.epaFehler('UNGUELTIGER_AUSLOESER', vorgangsId, `Auslöser "${e.ausloeser}" ist ungültig`);
const text = (w) => (w === undefined || w === null || w === '' ? null : String(w));
return [{ json: {
	kunde_id: e.kunde_id.trim(),
	vorgangs_id: vorgangsId,
	typ: e.typ,
	alt: text(e.alt),
	neu: text(e.neu),
	ausloeser: e.ausloeser.trim(),
	details: e.details && typeof e.details === 'object' && !Array.isArray(e.details) ? e.details : {},
	referenz: text(e.referenz) ?? String($execution.id),
} }];

